// Headless terrain columns for SpawnerAnimals (batch 21, natural-spawning.md "Headless ring").
//
// Natively every chunk SpawnerAnimals.findChunksForSpawning considers (the 15 x 15 non-edge chunks around the player) is loaded or
// generated by ChunkProviderServer.provideChunk, and so is any chunk a spawn attempt walks into (up to 20 blocks from a point in
// a chunk, so 2 chunks beyond the 15 x 15 set). A streamed world keeps only 8 x 8 resident columns, so the chunks outside it used
// to be skipped. This module keeps those columns as data only (no meshes, no light volume, no entities): the block ids of the
// generated terrain trimmed to the highest filled section, the nonzero metadata as a sorted sparse list, and the
// Chunk.getTopFilledSegment value. Memory is about 25 KB a column (about 11 MB for the whole 21 x 21 area).
//
// A column comes from the page's population cell cache, from a worker request (streaming-generator.js, type 'ring'), or from the
// world's own terrain generator in small per-tick budgets (Nether, End, terrain-only versions). Columns that are not there yet
// are skipped by the spawner exactly like before (no draws); once they arrive they take part with the native draw order.
// `view` is a World look-alike whose get/getMeta read the resident column first and a headless column second.
import { lightEmission, lightOpacity, LightVolume } from "./lighting.js";

// Chunks around the player that get a headless column: 7 (non-edge eligible) + 2 (a spawn attempt's reach) + 1 (light inflow).
export const RING_RADIUS = 10;
const KEEP = RING_RADIUS + 2; // hysteresis before a far column is dropped
const KEY = 8388608; // |chunk z| < 1,875,000 (the 30,000,000 border), so cx * 2^23 + cz is unique
export const ringKey = (cx, cz) => cx * KEY + cz;

// A column of {blocks, metadata} in WorldChunk order (index (lx * 16 + lz) * height + y), trimmed to its highest filled section.
export function compactColumn(blocks, metadata, height = 256) {
  let maxY = -1;
  for (let c = 0; c < 256; c++) {
    const base = c * height;
    for (let y = height - 1; y > maxY; y--) if (blocks[base + y]) { maxY = y; break; }
  }
  const topSection = maxY < 0 ? 0 : maxY >> 4, h = (topSection + 1) * 16, out = new Uint8Array(256 * h), meta = [];
  for (let c = 0; c < 256; c++) {
    const base = c * height;
    out.set(blocks.subarray(base, base + h), c * h);
    for (let y = 0; y < h; y++) {
      const m = metadata[base + y];
      if (m) meta.push(((c * h + y) << 4) | m);
    }
  }
  return { h, top: topSection * 16, blocks: out, meta: Uint32Array.from(meta) };
}

// The metadata of cell index i (c * h + y) of a compact column.
function metaOf(col, i) {
  const keys = col.meta;
  let lo = 0, hi = keys.length - 1;
  const want = i << 4;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1, k = keys[mid];
    if (k >> 4 === i) return k & 15;
    if (k < want) lo = mid + 1; else hi = mid - 1;
  }
  return 0;
}

export class HeadlessColumns {
  // `world`: the streamed World (or a DimensionWorld). `generate(cx, cz)`: optional synchronous source of
  // { blocks, metadata } used at `perTick` columns every `every` ticks (never for the Overworld's populated versions, whose cells
  // take about a second); `worker`: true when requests go to the generation worker.
  constructor(world, { generate = null, perTick = 1, every = 1, pull = 6, radius = RING_RADIUS } = {}) {
    this.world = world;
    this.height = world.height ?? 256;
    this.radius = radius;
    this.keep = radius + 2;
    this.generate = generate; this.perTick = perTick; this.every = every; this.pullBudget = pull;
    this.cols = new Map();
    this.cx = NaN; this.cz = NaN;
    this.queue = []; this.dirty = true;
    this.calls = 0;
    this.last = null; this.lastKey = NaN;
    this.cells = !!world.population && world.generationVersion >= 13 && !world.dimension;
    this.light = new RingLight(this);
    this.stats = { pulled: 0, generated: 0, received: 0, pruned: 0 };
    const view = Object.create(world);
    view.get = (x, y, z) => this.get(x, y, z);
    view.getMeta = (x, y, z) => this.getMeta(x, y, z);
    this.view = view;
  }
  resident(x, z) { const w = this.world; return x >= w.minX && x < w.maxX && z >= w.minZ && z < w.maxZ; }
  column(cx, cz) {
    const k = ringKey(cx, cz);
    if (k === this.lastKey) return this.last;
    const c = this.cols.get(k);
    if (c) { this.last = c; this.lastKey = k; }
    return c;
  }
  // Is the block at (x, z) in a chunk the spawner can read (resident, or with a headless column)?
  holds(x, z) { return this.resident(x, z) || this.cols.has(ringKey(x >> 4, z >> 4)); }
  // True for a chunk that has a headless column and no resident one (its light comes from RingLight, not the scene).
  outside(x, z) { return !this.resident(x, z) && this.cols.has(ringKey(x >> 4, z >> 4)); }
  get(x, y, z) {
    if (y < 0 || y >= this.height) return 0;
    if (this.resident(x, z)) return this.world.get(x, y, z);
    const col = this.column(x >> 4, z >> 4);
    if (!col || y >= col.h) return 0;
    return col.blocks[((x & 15) * 16 + (z & 15)) * col.h + y];
  }
  getMeta(x, y, z) {
    if (y < 0 || y >= this.height) return 0;
    if (this.resident(x, z)) return this.world.getMeta(x, y, z);
    const col = this.column(x >> 4, z >> 4);
    if (!col || y >= col.h) return 0;
    return metaOf(col, ((x & 15) * 16 + (z & 15)) * col.h + y);
  }
  // Chunk.getTopFilledSegment of a headless column, or -1.
  top(cx, cz) { return this.column(cx, cz)?.top ?? -1; }
  add(cx, cz, col) {
    if (this.near(cx, cz, this.keep)) { this.cols.set(ringKey(cx, cz), col); this.dirty = true; this.light.clear(); this.lastKey = NaN; }
  }
  near(cx, cz, r) { return Math.abs(cx - this.cx) <= r && Math.abs(cz - this.cz) <= r; }
  // Called every spawner tick with the player's chunk (world-local coordinates). Re-centres, drops far columns and fills missing
  // ones from what is already built, within budgets.
  update(pcx, pcz) {
    if (pcx !== this.cx || pcz !== this.cz) {
      this.cx = pcx; this.cz = pcz; this.dirty = true;
      for (const [k, c] of this.cols) {
        const cz = ((k % KEY) + KEY + KEY / 2) % KEY - KEY / 2, cx = (k - cz) / KEY;
        if (!this.near(cx, cz, this.keep)) { this.cols.delete(k); this.stats.pruned++; this.lastKey = NaN; }
      }
      this.light.clear();
    }
    if (this.dirty) this.rebuildQueue();
    if (!this.queue.length) return;
    this.calls++;
    let pulled = 0;
    const cache = this.cells ? this.world.population.cells.map : null;
    for (let i = 0; i < this.queue.length && pulled < this.pullBudget; i++) {
      const [cx, cz] = this.queue[i];
      if (this.cols.has(ringKey(cx, cz))) continue;
      const cell = cache?.get(`${cx >> 3},${cz >> 3}`), src = cell?.columns.get(`${cx},${cz}`);
      if (!src) continue;
      this.cols.set(ringKey(cx, cz), compactColumn(src.blocks, src.metadata, this.height));
      pulled++; this.stats.pulled++;
    }
    if (pulled) { this.dirty = true; this.light.clear(); this.lastKey = NaN; }
    if (this.generate && this.calls % this.every === 0) {
      let made = 0;
      for (let i = 0; i < this.queue.length && made < this.perTick; i++) {
        const [cx, cz] = this.queue[i];
        if (this.cols.has(ringKey(cx, cz))) continue;
        const g = this.generate(cx, cz);
        if (!g) continue;
        this.cols.set(ringKey(cx, cz), compactColumn(g.blocks, g.metadata, this.height));
        made++; this.stats.generated++;
      }
      if (made) { this.dirty = true; this.light.clear(); this.lastKey = NaN; }
    }
  }
  // Chunks within the radius that have no headless column, nearest first.
  rebuildQueue() {
    this.dirty = false;
    const r = this.radius, out = [];
    for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
      const cx = this.cx + dx, cz = this.cz + dz;
      if (!this.cols.has(ringKey(cx, cz))) out.push([cx, cz, dx * dx + dz * dz]);
    }
    out.sort((a, b) => a[2] - b[2]);
    this.queue = out;
  }
  // Units the worker should build next, nearest first: population cells [cellX, cellZ] for generation 13 and later, otherwise
  // chunks. Units already cached on the page are excluded (update() pulls those without a worker).
  units() {
    if (this.dirty) this.rebuildQueue();
    if (this.generate) return [];
    const out = new Map(), cache = this.cells ? this.world.population.cells.map : null;
    for (const [cx, cz] of this.queue) {
      if (this.cells) {
        const ux = cx >> 3, uz = cz >> 3;
        if (cache.has(`${ux},${uz}`)) continue;
        out.set(`${ux},${uz}`, [ux, uz]);
      } else out.set(`${cx},${cz}`, [cx, cz]);
      if (out.size >= 4) break;
    }
    return [...out.values()];
  }
  // A worker reply: [[cx, cz, compact]] for one cell or column.
  receive(columns) {
    for (const [cx, cz, col] of columns) if (!this.cols.has(ringKey(cx, cz))) { this.add(cx, cz, col); this.stats.received++; }
  }
  get size() { return this.cols.size; }
  bytes() {
    let n = 0;
    for (const c of this.cols.values()) n += c.blocks.byteLength + c.meta.byteLength;
    return n;
  }
}

// Sky and block light of a cell in a headless column, computed on demand at World.computeLightValue's fixed point (the one
// LightVolume keeps for the resident window): a cell takes its brightest neighbour minus max(1, opacity); cells at or above a
// column's height map see the sky at 15. A reverse search from the queried cell finds the best source within 14 steps, which is
// the same maximum over paths, so the value equals the volume's wherever the surrounding columns are present. Columns that are
// missing read as air, so a cell within 15 blocks of the headless area's rim can read brighter than natively.
const OPACITY = new Uint8Array(256), EMISSION = new Uint8Array(256), COST = new Uint8Array(256);
for (let b = 0; b < 256; b++) {
  const op = Math.min(255, lightOpacity(b)), e = lightEmission(b);
  OPACITY[b] = op; EMISSION[b] = e;
  COST[b] = op >= 15 && e > 0 ? 1 : Math.max(1, Math.min(15, op));
}
const R = 14, W = 2 * R + 1;
export class RingLight {
  constructor(ring) {
    this.ring = ring;
    this.emission = (x, y, z, b) => lightEmission(b);
    this.cache = new Map();
    this.heights = new Map();
    this.grid = new Int8Array(W * W * W);
    this.queries = 0;
  }
  get world() { return this.ring.view; } // LightVolume.packed reads blocks through world.get
  clear() { if (this.cache.size) this.cache.clear(); if (this.heights.size) this.heights.clear(); }
  // The first y from the top whose block has any opacity, plus one (LightVolume.column).
  heightAt(x, z) {
    const k = x * 2147483648 + z, hit = this.heights.get(k);
    if (hit !== undefined) return hit;
    const ring = this.ring;
    let y = ring.height - 1;
    const col = ring.resident(x, z) ? null : ring.column(x >> 4, z >> 4);
    if (col) y = col.h - 1;
    while (y >= 0 && OPACITY[ring.get(x, y, z)] === 0) y--;
    this.heights.set(k, y + 1);
    return y + 1;
  }
  // [sky, block] of a cell.
  at(x, y, z) {
    const k = (x * 2147483648 + z) * 256 + y, hit = this.cache.get(k);
    if (hit !== undefined) return hit;
    const r = this.search(x, y, z);
    this.cache.set(k, r);
    return r;
  }
  skyAt(x, y, z) {
    if (y >= this.ring.height) return 15;
    return this.at(x, Math.max(0, y), z) >> 4;
  }
  blockAt(x, y, z) {
    if (y >= this.ring.height) return 0;
    return this.at(x, Math.max(0, y), z) & 15;
  }
  search(qx, qy, qz) {
    this.queries++;
    const ring = this.ring, H = ring.height, noSky = ring.world.hasNoSky;
    const init = (x, y, z, b) => [!noSky && y >= this.heightAt(x, z) ? 15 : 0, EMISSION[b]];
    const qb = ring.get(qx, qy, qz);
    let [sky, block] = init(qx, qy, qz, qb);
    if (COST[qb] >= 15) return sky << 4 | block;
    // Reverse Dijkstra over cells reached through receiving cells: acc is the summed cost of the cells after the node on its path.
    const grid = this.grid;
    grid.fill(127);
    const at = (dx, dy, dz) => ((dx + R) * W + dy + R) * W + dz + R;
    const buckets = Array.from({ length: R + 1 }, () => []);
    grid[at(0, 0, 0)] = 0;
    buckets[0].push(0, 0, 0);
    const maxSky = sky;
    for (let acc = 0; acc <= R; acc++) {
      const list = buckets[acc];
      for (let q = 0; q < list.length; q += 3) {
        const dx = list[q], dy = list[q + 1], dz = list[q + 2];
        if (grid[at(dx, dy, dz)] !== acc) continue;
        const x = qx + dx, y = qy + dy, z = qz + dz, b = ring.get(x, y, z);
        if (acc > 0) {
          const s = !noSky && y >= this.heightAt(x, z) ? 15 - acc : 0, e = EMISSION[b] - acc;
          if (s > sky) sky = s;
          if (e > block) block = e;
        }
        const cost = COST[b];
        if (cost >= 15) continue; // a cell that cannot receive light does not carry it on
        const next = acc + cost;
        if (next > R) continue;
        for (let d = 0; d < 6; d++) {
          const ax = d === 0 ? 1 : d === 1 ? -1 : 0, ay = d === 2 ? 1 : d === 3 ? -1 : 0, az = d === 4 ? 1 : d === 5 ? -1 : 0;
          const nx = dx + ax, ny = dy + ay, nz = dz + az;
          if (Math.abs(nx) > R || Math.abs(ny) > R || Math.abs(nz) > R || qy + ny < 0 || qy + ny >= H) continue;
          const i = at(nx, ny, nz);
          if (next < grid[i]) { grid[i] = next; buckets[next].push(nx, ny, nz); }
        }
      }
    }
    void maxSky;
    return sky << 4 | block;
  }
}
RingLight.prototype.packed = LightVolume.prototype.packed;
RingLight.prototype.level = LightVolume.prototype.level;

// The ring for a played world, or null when every column is resident anyway (finite worlds). Populated Overworld versions
// (13 and later) are fed by the generation worker and the page's cell cache only; Nether, End and terrain-only versions without a
// worker generate a column every other tick from the world's own terrain source (about 37 ms a Nether column, so about 30 s to fill).
export function createRing(world, { worker = false } = {}) {
  if (!world.streaming || !world.generateTerrainChunk) return null;
  const populated = !!world.population && world.generationVersion >= 13 && !world.dimension;
  if (populated || (worker && !world.dimension)) return new HeadlessColumns(world);
  const source = (cx, cz) => {
    const k = `${cx},${cz}`;
    return world.pregenerated?.get(k) ?? world.baseColumns?.get(k) ?? world.generateTerrainChunk(cx, cz);
  };
  return new HeadlessColumns(world, { generate: source, perTick: 1, every: 2 });
}
